    result_handled = False
    prefixes = dict(cards_list='lookup_response.data.data.', cards_balance='balance_lookup_response.data.data.', contact_email_get='contact_lookup_response.data.data.', statement_week_get='week_lookup_response.data.data.', statement_week_decide='preview_lookup_response.data.data.', statement_week_change='change_write_response.data.data.', statement_pdf_send='email_write_response.data.data.')
    if event:
