    def payload(value, prefix, v=vars, dec=decode):
        data = dec(value) if value else {}
        if isinstance(data, dict) and data:
            return data
        tree = {}
        if not prefix:
            return tree
        for key, raw in v.items():
            if not key.startswith(prefix):
                continue
            parts = key[len(prefix):].split('.')
            branch = tree
            for part in parts[:-1]:
                branch = branch.setdefault(part, {})
            val = raw
            if raw == 'true':
                val = True
            elif raw == 'false':
                val = False
            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):
                val = dec(raw)
            branch[parts[-1]] = val
        if isinstance(tree.get('cards'), dict):
            tree['cards'] = [tree['cards'][k] for k in sorted(tree['cards'], key=lambda x: int(x))]
        return tree
    def current_list_warning(prefix, baseline, v=vars, js=json):
        count = int(v.get(prefix + '_failure_count', 0) or 0)
        seen = int(v.get(prefix + '_error_seen', 0) or 0)
        if count <= max(int(baseline), seen):
            return False
        v[prefix + '_error_seen'] = count
        transport = str(v.get(prefix + '_response.status', ''))
        status = str(v.get(prefix + '_response.status_code') or v.get(prefix + '_status_code') or '')
        if transport != 'error' or status != '404':
            return False
        bodies = []
        raw_body = v.get(prefix + '_response.data', {})
        if isinstance(raw_body, dict):
            bodies.append(raw_body)
        raw_result = v.get(prefix + '_response.data.result', {})
        if isinstance(raw_result, dict) and raw_result:
            bodies.append(dict(result=raw_result))
        rc = str(v.get(prefix + '_response.data.result.returnCode', ''))
        rt = str(v.get(prefix + '_response.data.result.type', ''))
        if rc and rt:
            bodies.append(dict(result=dict(returnCode=rc, code=str(v.get(prefix + '_response.data.result.code', '') or rc), type=rt)))
        for raw in [raw_body, v.get(prefix + '_response.message', '')]:
            if not isinstance(raw, str):
                continue
            for position, char in enumerate(raw):
                if char != '{':
                    continue
                try:
                    parsed, consumed = js.JSONDecoder().raw_decode(raw[position:])
                    if isinstance(parsed, dict) and isinstance(parsed.get('result'), dict):
                        bodies.append(parsed)
                except ValueError:
                    continue
        for body in bodies:
            outcome = body.get('result', {})
            if isinstance(outcome, dict) and outcome.get('returnCode') == 'FB_IVR_CHANNEL_102' and outcome.get('code', 'FB_IVR_CHANNEL_102') == 'FB_IVR_CHANNEL_102' and outcome.get('type') == 'WARNING':
                return True
        return False
