    vars['bank_event'] = ''
    vars['bank_pending'] = ''
    vars['bank_payload'] = {}
    vars['bank_response_prefix'] = ''
    vars['list_failure_baseline'] = 0
    if event or pending:
        vars['bank_status'] = 'idle'
    vars['stale_event_ignored'] = ''
    if event == 'cards_list' and vars.get('cards_ready') == 'yes' and vars.get('cards_customer') == str(vars.get('customerNumber', '')) and incoming_phase not in ['start', 'list_wait']:
        vars['stale_event_ignored'] = event
        event = ''
    vars['operation_before_error'] = event or 'evaluate'
    input_present = any(supplied.get(k) not in ['', 'neutral'] for k in keys)
    initial_selection = vars.get('selection_initial') == 'yes'
    vars['selection_initial'] = 'no'
    arrival = decode(vars.get('arrival_input', {}))
    if event == 'cards_list':
        vars['arrival_input'] = {}
        if arrival:
            if input_present:
                vars['deferred_input'] = dict(supplied)
            supplied = clean_input(arrival)
            kind = supplied['u_kind']
            input_present = any(supplied.get(k) not in ['', 'neutral'] for k in keys)
    request_text = supplied.get('u_detail_request', '').strip()
    detail_value = supplied.get('u_detail', 'neutral')
    if detail_value in ['all', 'due', 'minimum']:
        vars['wanted_detail'] = detail_value
        vars['detail_request'] = request_text
    elif detail_value == 'total':
        vars['wanted_detail'] = 'total' if total_only(request_text) else 'all'
        vars['detail_request'] = request_text
    elif request_text:
        vars['detail_request'] = request_text
        if total_only(request_text):
            vars['wanted_detail'] = 'total'
        elif re.search(r'ekstre|borc', norm(request_text)):
            vars['wanted_detail'] = 'all'
    if vars.get('wanted_detail') == 'total' and not total_only(vars.get('detail_request', '')):
        vars['wanted_detail'] = 'all'
    for key, target, values in [('u_followup', 'pending_followup', ['email', 'week']), ('u_currency', 'wanted_currency', codes + ['unclear']), ('u_period', 'wanted_period', ['latest', 'older'])]:
        if supplied.get(key) in values:
