    if not re.fullmatch(r'\d{8}', str(vars.get('customerNumber', ''))):
        raise ValueError('missing_trusted_customer')
    result_handled = False
    prefixes = dict(cards_list='lookup_response.data.data.', cards_balance='balance_lookup_response.data.data.', contact_email_get='contact_lookup_response.data.data.', statement_week_get='week_lookup_response.data.data.', statement_week_decide='preview_lookup_response.data.data.', statement_week_change='change_write_response.data.data.', statement_pdf_send='email_write_response.data.data.')
    if event:
        data = payload(event_payload, prefixes.get(event, '')) if event_status == 'ok' else {}
        result_handled = True
        vars['last_consumed_bank_event'] = event
        if event == 'cards_list' and event_status == 'no_cards':
            close('Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
        elif event_status != 'ok':
            message = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.' if event.startswith('statement_week_') else 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
            close(message, 'agent', True)
        elif event == 'cards_list':
            if 'cards' not in data:
                raise ValueError('missing_cards_field')
            cards = decode(data['cards'])
            if not isinstance(cards, list) or any(not isinstance(c, dict) for c in cards):
                raise ValueError('invalid_cards')
            if 'validCardsCount' in data and int(data['validCardsCount']) != len(cards):
                raise ValueError('inconsistent_card_count')
            vars['cards_private'] = cards
            vars['cards_customer'] = str(vars['customerNumber'])
