            blocks = [(code, label, data.get('debt' + code)) for code, label in zip(codes, labels) if isinstance(data.get('debt' + code), dict) and data.get('debt' + code)]
            cut_today = (bool(sd) and date_value(sd) == today) or (bool(nxt) and date_value(nxt) == today)
            late = bool(due) and date_value(due) < today
            mode = 'cut_day' if cut_today else ('new_card' if not sd else ('no_statement_debt' if data.get('statementPaymentStatus') == 'NO_DEBT' else ('overdue' if late else 'normal')))
            if cut_today and nxt and date_value(nxt) == today:
                due = str(data.get('nextLastPayDate', ''))
            vars['reading_mode'] = mode
            vars['no_statement_branch'] = 'yes' if mode in ['new_card', 'no_statement_debt'] else 'no'
            vars['tl_band'] = 'missing'
            tl = data.get('debtTL')
            if isinstance(tl, dict) and tl:
                rd, rm, mm = minor(tl['remainingDebt']), minor(tl['remainingMinPayment']), minor(tl['minPayment'])
                vars['tl_band'] = 'no_debt' if rd <= 0 else ('minimum_paid' if rm <= 0 else ('nothing_paid' if rm >= mm else 'below_minimum'))
            due_line = ''
            if due:
                if date_value(due) == today:
