            selected_blocks = [b for b in blocks if currency not in codes or b[0] == currency]
            lines = []
            vars['clear_currencies'] = []
            if detail == 'due':
                lines = [opening + 'kartınız için ' + (due_line or 'henüz bir son ödeme tarihi bulunmuyor.')]
            elif detail in ['minimum', 'total']:
                lines = [opening + 'kartınız için:']
                clear = []
                for code, label, block in selected_blocks:
                    field = 'minPayment' if detail == 'minimum' else 'totalDebt'
                    if minor(block[field]) > 0:
                        lines.append(label + (' minimum ödeme tutarınız ' if detail == 'minimum' else ' toplam borcunuz ') + money(block[field], code) + '.')
