    def week_allowed(card_key, v=vars):
        return str(v.get('changed_years', {}).get(card_key, '')) != str(v['call_year']) and card_key not in v.get('claimed_used_cards', [])
    def load_contact(next_phase, v=vars):
        if v.get('contact_ready') == 'yes':
            v['after_contact'] = ''
            v['phase'] = next_phase
        else:
            v['after_contact'] = next_phase
            v['phase'] = 'contact_wait'
            v['route'] = 'contact_lookup'
    def payload(value, prefix, v=vars, dec=decode):
        data = dec(value) if value else {}
        if isinstance(data, dict) and data:
            return data
        tree = {}
        if not prefix:
            return tree
        for key, raw in v.items():
            if not key.startswith(prefix):
                continue
            parts = key[len(prefix):].split('.')
            branch = tree
            for part in parts[:-1]:
                branch = branch.setdefault(part, {})
            val = raw
            if raw == 'true':
                val = True
            elif raw == 'false':
                val = False
            elif isinstance(raw, str) and raw.lstrip().startswith(('[', '{')):
                val = dec(raw)
            branch[parts[-1]] = val
        if isinstance(tree.get('cards'), dict):
            tree['cards'] = [tree['cards'][k] for k in sorted(tree['cards'], key=lambda x: int(x))]
        return tree
    def current_list_warning(prefix, baseline, v=vars, js=json):
        count = int(v.get(prefix + '_failure_count', 0) or 0)
        seen = int(v.get(prefix + '_error_seen', 0) or 0)
        if count <= max(int(baseline), seen):
            return False
        v[prefix + '_error_seen'] = count
        transport = str(v.get(prefix + '_response.status', ''))
        status = str(v.get(prefix + '_response.status_code') or v.get(prefix + '_status_code') or '')
        if transport != 'error' or status != '404':
            return False
        bodies = []
        raw_body = v.get(prefix + '_response.data', {})
        if isinstance(raw_body, dict):
            bodies.append(raw_body)
        raw_result = v.get(prefix + '_response.data.result', {})
        if isinstance(raw_result, dict) and raw_result:
            bodies.append(dict(result=raw_result))
        rc = str(v.get(prefix + '_response.data.result.returnCode', ''))
        rt = str(v.get(prefix + '_response.data.result.type', ''))
        if rc and rt:
            bodies.append(dict(result=dict(returnCode=rc, code=str(v.get(prefix + '_response.data.result.code', '') or rc), type=rt)))
        for raw in [raw_body, v.get(prefix + '_response.message', '')]:
            if not isinstance(raw, str):
                continue
            for position, char in enumerate(raw):
                if char != '{':
                    continue
                try:
                    parsed, consumed = js.JSONDecoder().raw_decode(raw[position:])
                    if isinstance(parsed, dict) and isinstance(parsed.get('result'), dict):
                        bodies.append(parsed)
                except ValueError:
                    continue
        for body in bodies:
            outcome = body.get('result', {})
            if isinstance(outcome, dict) and outcome.get('returnCode') == 'FB_IVR_CHANNEL_102' and outcome.get('code', 'FB_IVR_CHANNEL_102') == 'FB_IVR_CHANNEL_102' and outcome.get('type') == 'WARNING':
                return True
        return False
    kinds = ['neutral', 'answer', 'yes', 'no', 'unclear', 'refuse', 'repeat', 'silence', 'agent', 'pay', 'dispute', 'third_party', 'non_turkish', 'outside', 'angry', 'privacy', 'secret', 'all_cards', 'card', 'email', 'week', 'done', 'stop', 'undo', 'effective', 'ai']
    text_keys = ['u_card', 'u_digits', 'u_detail_request']
    enums = dict(u_kind=kinds, u_digit_mode=['neutral', 'append', 'replace'], u_detail=['neutral', 'all', 'due', 'minimum', 'total'], u_followup=['neutral', 'email', 'week'], u_currency=['neutral', 'TL', 'USD', 'EUR', 'GBP', 'unclear'], u_period=['neutral', 'latest', 'older'], u_week=['neutral', '1', '2', '3', '4', 'invalid'], u_destination=['neutral', 'registered', 'other', 'wrong', 'paper', 'sms'])
    keys = list(enums) + text_keys
    def clean_input(raw, fields=keys, texts=text_keys, options=enums, normalize_alias=alias):
        if not isinstance(raw, dict):
            raw = dict(u_kind='unclear')
        clean = {}
        invalid = False
        for name in fields:
            value = raw.get(name, '' if name in texts else 'neutral')
            if name in texts:
                if not isinstance(value, str):
                    invalid = True
                    value = ''
            elif value not in options[name]:
                invalid = True
                value = 'invalid' if name == 'u_week' else ('unclear' if name == 'u_currency' else 'neutral')
            clean[name] = value
        if clean['u_card'] and not normalize_alias(clean['u_card']):
            clean['u_card'] = ''
            if clean['u_kind'] == 'card' and not clean['u_digits']:
                clean['u_kind'] = 'answer'
        if invalid:
            clean['u_kind'] = 'unclear'
        return clean
    supplied = clean_input(dict((key, vars.get(key, '' if key in text_keys else 'neutral')) for key in keys))
